import re
from taf.sw.dcap.rd.exception import DcapVersionNotSupported
from taf.sw.dcap.rd.interfaces.dcapv1 import DCAPv1
from taf.sw.dcap.rd.interfaces.dcapv2 import DCAPv2
from taf.sw.dcap.rd.interfaces.dcapv3 import DCAPv3
from taf.sw.dcap.rd.auth.authorization import TokenManager


class ConnectionDetails(object):
    def __init__(self, host, port, username, password, secure=False, timeout=None):
        self.protocol = 'http://'
        self.host = host
        self.port = port
        self.secure = secure
        self.username = username
        self.password = password
        self.timeout = int(timeout) if timeout else None

        if self.secure is True:
            self.protocol = 'https://'
        self.base_url = '{protocol}{host}:{port}/apigw'.format(protocol=self.protocol,
                                                               host=self.host,
                                                               port=self.port)

    def make_configuration_host(self, original_endpoint):
        endpoint_match = re.match(r'^http.*localhost', original_endpoint)
        endpoint = original_endpoint.replace(endpoint_match.group(), '')
        original_endpoint = '{base_url}{endpoint}'.format(base_url=self.base_url,
                                                          endpoint=endpoint)
        return original_endpoint


class SupportedDCAPs(object):
    dcapv1 = DCAPv1
    dcapv2 = DCAPv2
    dcapv3 = DCAPv3


class DcapProvider(object):
    @classmethod
    def create_dcap(cls, host, port, username, password, rd_version, secure=False, timeout=None):
        dcap_type = getattr(SupportedDCAPs, rd_version, None)

        if not dcap_type:
            exception_message = 'Version {} of dcap is not supported'.format(rd_version)
            raise DcapVersionNotSupported(exception_message)
        if username:
            token = TokenManager(host, port, username, password)
            con_details = ConnectionDetails(
                host=host, port=port, username=username, password=password, secure=secure, timeout=timeout)
            dcap = dcap_type(con_details, token)
        else:
            con_details = ConnectionDetails(host=host, port=port, username=username, password=password, secure=secure,
                                            timeout=timeout)
            dcap = dcap_type(con_details)
        return dcap
